import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)
app.secret_key = 'your-secret-key-here'

DATA_ROOT = '/data'


def safe_join(base, *paths):
    """Join base with subpaths and resolve to an absolute path, preventing path traversal."""
    joined = os.path.abspath(os.path.join(base, *paths))
    if not joined.startswith(base):
        raise ValueError("Invalid path traversal detected")
    return joined


@app.route('/search', methods=['POST'])
def search():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Invalid JSON body"}), 400

    search_content = data.get('search_content')
    search_filename = data.get('search_filename')
    search_dir = data.get('search_dir')

    if not isinstance(search_content, str) and search_content is not None:
        return jsonify({"error": "search_content must be a string or null"}), 400
    if not isinstance(search_filename, str) and search_filename is not None:
        return jsonify({"error": "search_filename must be a string or null"}), 400
    if not isinstance(search_dir, str) and search_dir is not None:
        return jsonify({"error": "search_dir must be a string or null"}), 400

    base_path = safe_join(DATA_ROOT, search_dir) if search_dir else DATA_ROOT

    if not os.path.isdir(base_path):
        return jsonify({"error": f"Directory {base_path} does not exist"}), 400

    results = []

    # Compile regex patterns if content is provided
    content_pattern = re.compile(re.escape(search_content), re.IGNORECASE) if search_content else None

    for root, dirs, files in os.walk(base_path):
        # Prevent descending into paths that escape the base
        if not root.startswith(base_path):
            continue
        for file in files:
            filepath = os.path.join(root, file)
            try:
                # Check filename
                if search_filename and file.startswith(search_filename):
                    results.append(filepath)
                    continue  # Avoid double-adding if content also matches
                # Check content
                if content_pattern and content_pattern.search(file.read_text(errors='ignore')):
                    results.append(filepath)
            except (UnicodeDecodeError, PermissionError, OSError):
                # Skip binary or inaccessible files
                continue

    return jsonify({"files": sorted(set(results))})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

